        "code": "too_small",
        "exact": true,
        "inclusive": true,
        "message": "Too small: expected array to have exactly 2 items",
        "minimum": 2,
        "origin": "array",
        "path": [],
      },
    ]
  `);

  const r2 = schema.safeParse(["asdf", "asdf", "asdf"]);
  expect(r2.success).toEqual(false);
