import Benchmark from "benchmark";
import chalk from "chalk";
import { Table } from "console-table-printer";
import * as mitata from "mitata";
import { Bench } from "tinybench";

// import { assertNever } from "../packages/zod-core/src/index.js";
import { formatNumber } from "./benchUtil.js";

type BENCH = "tinybench" | "benchmarkjs" | "mitata";
const BENCH: BENCH = (process.env.BENCH as BENCH) || "tinybench";

type Benchmarks<T = unknown> = { [k: string]: (d: T) => any };
export function metabench<D>(name: string, benchmarks?: Benchmarks<D>): Metabench {
  let bench: Metabench;
  if (BENCH === "tinybench") {
    bench = new Tinybench(name, benchmarks || {});
  } else if (BENCH === "benchmarkjs") {
    bench = new BenchmarkJS(name, benchmarks || {});
  } else if (BENCH === "mitata") {
    bench = new Mitata(name, benchmarks || {});
  } else {
    throw new Error(`Unknown benchmark runner: ${BENCH}`);
  }
  // console.log(`running benchmark with ${BENCH}...`);
  return bench;
}

interface BenchWithDataParams<D> {
  name: string;
  data: () => D;
  batch?: number | null;
  benchmarks?: Benchmarks<D>;
}

export function benchWithData<D>(params: BenchWithDataParams<D> & ThisType<{ data: D }>): Metabench<D> {
  const bench = metabench(params.name);
  // console.log(`Batch size: ${params.batch}`);

  if (params.batch === null) {
    const DATA = params.data();
    for (const key in params.benchmarks) {
      const _bench = params.benchmarks[key].bind({
        data: DATA,
      }) as any;
      bench.add(key, _bench);
    }
  } else {
    const DATA = Array.from({ length: params.batch || 1000 }, params.data);
    for (const key in params.benchmarks) {
      const _bench = params.benchmarks[key].bind({
        data: DATA,
      }) as any;
      bench.add(key, () => {
        for (const d of DATA) {
          _bench(d);
        }
      });
    }
  }

  return bench;
}

abstract class Metabench<D = any> {
  abstract run(): void | Promise<void>;

  constructor(
    public name: string,
    public benchmarks: Benchmarks<D>
    //  params?: Omit<MetabenchParams<D>, "name" | "benchmarks">
  ) {}

  add(name: string, fn: (val: D) => any): this {
    this.benchmarks![name] = fn;
    return this;
  }
}

class Tinybench extends Metabench {
  runner = "tinybench";
  async run() {
    const bench = new Bench({ time: 1500 });
    for (const [name, fn] of Object.entries(this.benchmarks)) {
      bench.add(name, fn as any);
    }
    // await runBench(this.name, bench);
    console.log();
    console.log(`   benchmarking ${chalk.bold.white(this.name)} with ${chalk.bold.white(this.runner)}`);

    bench.addEventListener("cycle", (e) => {
      const task = e.task?.result;
      if (!task) throw new Error("Task has no result");

      console.log(
        chalk.dim("   ") +
          chalk.white.dim(`→ `) +
          chalk.white(e.task.name) +
          chalk.white.dim(" ") +
          chalk.cyan(formatNumber(task.hz)) +
          chalk.cyan(` ops/sec`) +
          chalk.dim(` (${e.task.result?.totalTime.toFixed(2)}ms)`)
      );
    });

    await bench.warmup();
    await bench.run();

    const sorted = bench.tasks.sort((a, b) => {
      if (!a.result || !b.result) throw new Error("Task has no result");
      return a.result?.mean - b.result?.mean;
    });
    // const fastest = sorted[0];
    const slowest = sorted[sorted.length - 1];

    const table = new Table({
      columns: [
        { name: "name", color: "white" },
        { name: "summary", alignment: "left" },
        { name: "ops/sec", color: "cyan" },
        { name: "time/op", color: "magenta" },
        { name: "margin", color: "magenta" },
        { name: "samples", color: "magenta" },
      ],
    });

    for (const task of sorted) {
      const result = task.result;
      if (!result) throw new Error("Task has no result");
      if (!slowest.result) throw new Error("Task has no result");
      table.addRow({
        name: task.name,
        summary:
          task === slowest ? "slowest" : `${(result.hz / slowest.result.hz).toFixed(3)}x faster than ${slowest.name}`,
        "ops/sec": `${formatNumber(result.hz)} ops/sec`,
        "time/op": `${formatNumber(result.mean / 1000)}s`,
        margin: `±${result.rme.toFixed(2)}%`,
        samples: result.samples.length,
      });
    }
    const rendered = `   ${table.render().split("\n").join("\n   ")}`;
    console.log();
    console.log(rendered);
    console.log();
  }
}

class BenchmarkJS extends Metabench {
  runner = "benchmarkjs";
  async run() {

import { defineConfig, mergeConfig } from "vitest/config";
import rootConfig from "../../vitest.root.mjs";

export default mergeConfig(
  rootConfig,
  defineConfig({
    test: {
      globals: true,
      environment: "node",
      typecheck: {
        enabled: false,
      },
    },
  })
) as object;

import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import ts from "typescript";

// Flags stacked `//` comments that hold prose. Lines are never hard-wrapped in this repo — the editor wraps for display — so a paragraph broken across several `//` lines belongs on one long line. Commented-out code, pragmas and list items are exempt; joining those would destroy them.
//
// A block is judged as a whole: unless every line reads as prose, the block is left alone. Classifying line by line would let one code-ish line split a paragraph, and `--fix` would then join the fragment and strand its tail.

const IGNORED_PREFIXES = ["packages/treeshake/", "packages/docs/", "packages/docs-v3/", "packages/integration/"];

const DIRECTIVE =
  /^(?:@ts-|@__|biome-ignore|eslint|prettier-ignore|oxlint|[cv]8 ignore|#(?:region|endregion)|\/|<reference)/;

/** A bullet or numbered item. Starts a fresh block, so a list survives but a wrapped item is still caught. */
const LIST_ITEM = /^(?:[-*•+]\s|\d+[.)]\s)/;

/** Declarations, spelled tightly enough that English keeps clear of them — `class instances collapse to …` is prose, `class Foo {` is not. */
const DECLARATION =
  /^(?:import\s+(?:type\s+)?(?:[{*]|\w+\s*[,{]|\w+\s+from\b)|import\s*["']|export\s+(?:default|const|let|var|function|class|interface|type|enum|abstract|declare|async|[*{])|(?:const|let|var)\s+[\w${[][^=]*=|(?:function|class|interface|enum|namespace|module)\s+\w+\s*[<({]|declare\s+\w)/;

/** Structure that never shows up in an English sentence. Not overridable by `looksLikeEnglish`. */
function hasCodeStructure(body: string): boolean {
  return (
    /[;{([<]$/.test(body) ||
    /^[)}\]>?:|&.]/.test(body) ||
    /^["'[]/.test(body) ||
    /^[A-Z]\w*\s+extends\s/.test(body) ||
    /^[\w$.[\]]+\s*=[^=]/.test(body) ||
    DECLARATION.test(body)
  );
}

/** Weaker hints, all of which prose also uses. A body that reads as English wins over these. */
function hasCodeHints(body: string): boolean {
  return (
    /[,:]$/.test(body) ||
    /`/.test(body) ||
    /=>|&&|\|\||\?\?|===|!==|\+\+/.test(body) ||
    /^[\w$.[\]"']+[<(]/.test(body) ||
    /^\w+\s*:\s*[\w$]+[.<([]/.test(body) ||
    /^(?:type|return|throw|await|async|if|else|for|while|do|switch|case|try|catch|finally|new|delete|yield|readonly|static|public|private|protected|abstract|class|interface|function|import|export|const|let|var|enum|namespace|declare)\b/.test(
      body
    )
  );
}

function looksLikeEnglish(body: string): boolean {
  const words = body.split(/\s+/).filter(Boolean);
  if (words.length < 3) return false;
  const wordy = words.filter((w) => /^[A-Za-z][A-Za-z'-]*[.,;:!?)]?$/.test(w)).length;
  return wordy / words.length >= 0.6;
}

function isProse(body: string): boolean {
  if (hasCodeStructure(body)) return false;
  return looksLikeEnglish(body) || !hasCodeHints(body);
}

interface Block {
  line: number;
  bodies: string[];
}

/** Line-owning `//` comments, keyed by zero-based line number. Trailing `// note` after code never stacks. */
function ownLineComments(fileName: string, text: string, lines: string[]): Map<number, string> {
  const sf = ts.createSourceFile(fileName, text, ts.ScriptTarget.Latest, /* setParentNodes */ false);

  // Every comment is leading or trailing trivia of some token, so walking the tree finds them all — and the parser has already told strings, templates and regexes apart from real comments for us.
  const starts = new Set<number>();
  const collect = (ranges: ts.CommentRange[] | undefined) => {
    for (const r of ranges ?? []) {
      if (r.kind === ts.SyntaxKind.SingleLineCommentTrivia) starts.add(r.pos);
    }
  };
  const visit = (node: ts.Node) => {
    collect(ts.getLeadingCommentRanges(text, node.pos));
    collect(ts.getTrailingCommentRanges(text, node.end));
    node.forEachChild(visit);
  };
  visit(sf);
  collect(ts.getLeadingCommentRanges(text, sf.endOfFileToken.pos));

  const owned = new Map<number, string>();
  for (const pos of starts) {
    const { line, character } = sf.getLineAndCharacterOfPosition(pos);
    if (lines[line].slice(0, character).trim() !== "") continue;
    owned.set(line, lines[line].trim().slice(2).trim());
  }
  return owned;
}

function proseBlocks(fileName: string, text: string, lines: string[]): Block[] {
  const owned = ownLineComments(fileName, text, lines);
  const blocks: Block[] = [];

  for (const line of [...owned.keys()].sort((a, b) => a - b)) {
    const body = owned.get(line)!;
    // A bare `//` is a paragraph break, and a directive belongs to whatever it annotates. Both end the block rather than joining it.
    if (body === "" || DIRECTIVE.test(body)) continue;
    const last = blocks.at(-1);
    if (last && last.line + last.bodies.length === line && !LIST_ITEM.test(body)) last.bodies.push(body);
    else blocks.push({ line, bodies: [body] });
  }

  return blocks.filter((b) => b.bodies.length > 1 && b.bodies.every(isProse));
}

function trackedFiles(): string[] {
  const paths = execFileSync("git", ["ls-files", "-z", "*.ts", "*.mts", "*.cts"], { encoding: "utf8" }).split("\0");
  // Dedupe: `git ls-files` repeats an unmerged path once per conflict stage, which would triple-count a file mid-rebase.
  return [...new Set(paths)].filter(
    (f) => f && !/\.d\.[cm]?ts$/.test(f) && !IGNORED_PREFIXES.some((p) => f.startsWith(p))
  );
}

const fix = process.argv.includes("--fix");
let violations = 0;
let touched = 0;

for (const file of trackedFiles()) {
  const text = readFileSync(file, "utf8");
  const lines = text.split("\n");
  const blocks = proseBlocks(file, text, lines);
  if (blocks.length === 0) continue;
  violations += blocks.length;

  if (fix) {
    for (const block of blocks) {
      const indent = lines[block.line].match(/^[ \t]*/)![0];
      lines[block.line] = `${indent}// ${block.bodies.join(" ")}`;
      for (let i = 1; i < block.bodies.length; i++) lines[block.line + i] = null as unknown as string;
    }
    writeFileSync(file, lines.filter((l) => l !== null).join("\n"));
    touched++;
    continue;
  }

  for (const block of blocks) {
    console.error(`${file}:${block.line + 1}: ${block.bodies.length} stacked comment lines`);
    for (const body of block.bodies) console.error(`    // ${body}`);
  }
}

if (violations === 0) {
  console.log("✅ No stacked comment lines");
} else if (fix) {
  console.log(`✅ Joined ${violations} stacked comment block(s) across ${touched} file(s)`);
} else {
  console.error(
    `\n❌ ${violations} stacked comment block(s). Join each into one line, or run \`nub run check:comments --fix\`.`
  );
  process.exit(1);
}

import semver from "semver";

// every zod release from 4.5.0 on must have an @zod/mini twin on npm and on JSR, and every @zod/mini 4.x must have a zod twin; latest must agree. `--wait` retries for up to ~6 minutes, since the npm packument endpoint is CDN-cached for five
const FLOOR = "4.5.0";
const attempts = process.argv.includes("--wait") ? 13 : 1;

type Releases = { name: string; versions: string[]; latest: string };

function stable(versions: string[]): string[] {
  return versions.filter((v) => semver.valid(v) && !semver.prerelease(v) && semver.gte(v, FLOOR));
}

async function npmReleases(name: string): Promise<Releases> {
  const res = await fetch(`https://registry.npmjs.org/${name.replace("/", "%2f")}`, {
    headers: { accept: "application/vnd.npm.install-v1+json" },
  });
  if (!res.ok) throw new Error(`npm registry ${res.status} for ${name}`);
  const body = (await res.json()) as { versions: Record<string, unknown>; "dist-tags": Record<string, string> };
  return { name, versions: stable(Object.keys(body.versions)), latest: body["dist-tags"].latest };
}

// a 404 means the package has no versions on JSR yet
async function jsrReleases(name: string): Promise<Releases> {
  const res = await fetch(`https://jsr.io/${name}/meta.json`);
  if (res.status === 404) return { name: `jsr:${name}`, versions: [], latest: "" };
  if (!res.ok) throw new Error(`jsr ${res.status} for ${name}`);
  const body = (await res.json()) as { versions: Record<string, unknown>; latest: string };
  return { name: `jsr:${name}`, versions: stable(Object.keys(body.versions)), latest: body.latest };
}

function twins(a: Releases, b: Releases): string[] {
  const out: string[] = [];
  const missing = a.versions.filter((v) => !b.versions.includes(v)).sort(semver.compare);
  const stray = b.versions.filter((v) => !a.versions.includes(v)).sort(semver.compare);
  if (missing.length) out.push(`${a.name} versions with no ${b.name} twin: ${missing.join(", ")}`);
  if (stray.length) out.push(`${b.name} versions with no ${a.name} twin: ${stray.join(", ")}`);
  if (a.latest !== b.latest) out.push(`latest differs: ${a.name}@${a.latest} vs ${b.name}@${b.latest}`);
  return out;
}

async function problems(): Promise<string[]> {
  const [zod, mini, jsrZod, jsrMini] = await Promise.all([
    npmReleases("zod"),
    npmReleases("@zod/mini"),
    jsrReleases("@zod/zod"),
    jsrReleases("@zod/mini"),
  ]);
  const out = [...twins(zod, mini), ...twins(jsrZod, jsrMini)];
  // npm is the source of truth and JSR follows it; a gap here is reported, not fatal, because that publish is recovered by hand and must not hold a release red
  for (const gap of twins(zod, jsrZod)) console.warn(`⚠️  ${gap}`);
  if (!out.length) {
    console.log(
      `✅ zod and @zod/mini are in lockstep on npm and JSR (${zod.versions.length} versions since ${FLOOR}, latest ${zod.latest})`
    );
  }
  return out;
}

let found = await problems();
for (let i = 1; i < attempts && found.length; i++) {
  console.log(`   not yet in lockstep (${found.join("; ")}); retrying in 30s (${i}/${attempts - 1})`);
  await new Promise((r) => setTimeout(r, 30_000));
  found = await problems();
}
if (found.length) {
  console.error(`❌ zod and @zod/mini are out of lockstep:`);
  for (const p of found) console.error(`   ${p}`);
  process.exit(1);
}

